let moonGlobe:T.Mesh,groundFacilities:T.Group,planetMaterial:ReturnType<typeof surfaceMaterial>,patchMaterial:ReturnType<typeof surfaceMaterial>;function buildTestWorld(environment:string,time:number){disposeWorld();groundFacilities=new T.Group();testWorld.add(groundFacilities);const color=environment==='water'?'#164c64':'#627569';planetMaterial=surfaceMaterial(environment==='water');const globe=new T.Mesh(new T.SphereGeometry(PLANET.radius,256,128),planetMaterial);globe.layers.set(1);globe.position.copy(center);testWorld.add(globe);moonGlobe=new T.Mesh(new T.SphereGeometry(MOON.radius,192,96),mat('#92918d',0,1));moonGlobe.layers.set(1);moonGlobe.position.copy(bodyState(MOON,time).position);testWorld.add(moonGlobe);const geometry=new T.PlaneGeometry(4000,4000,64,64);geometry.rotateX(-Math.PI/2);const positions=geometry.attributes.position;for(let i=0;i<positions.count;i++){const x=positions.getX(i),z=positions.getZ(i);positions.setY(i,Math.sqrt(PLANET.radius**2-x*x-z*z)-PLANET.radius+.01);}geometry.computeVertexNormals();patchMaterial=surfaceMaterial(environment==='water');surfacePatch=new T.Mesh(geometry,patchMaterial);S.flightScenery=new FlightScenery(testWorld);surfacePatch.receiveShadow=true;testWorld.add(surfacePatch);if(environment!=='water'){addLaunchpad(groundFacilities,assets.get('launchpad'));addSurveyMarkers(groundFacilities,assets);const runwaySite=new T.Group();runwaySite.quaternion.copy(launchSiteOrientation('runway'));runwaySite.position.set(0,PLANET.radius,0).applyQuaternion(runwaySite.quaternion);groundFacilities.add(runwaySite);const runwayGeometry=new T.PlaneGeometry(RUNWAY.width,RUNWAY.length,1,80);runwayGeometry.rotateX(-Math.PI/2);runwayGeometry.translate(0,0,RUNWAY.center);const rp=runwayGeometry.attributes.position;for(let i=0;i<rp.count;i++)rp.setY(i,.025-(rp.getX(i)**2+rp.getZ(i)**2)/(2*PLANET.radius));runwayGeometry.computeVertexNormals();const runway=new T.Mesh(runwayGeometry,mat('#3a4245'));runway.receiveShadow=true;runwaySite.add(runway);for(let z=-40;z<1400;z+=22)box(runwaySite,[.25,.01,8],[0,.035-z*z/(2*PLANET.radius),z],mat('#d8d7bd'));}}
