const dockingPilot=new DockingAutopilot();
const PILOT_KEYS=new Set(['KeyW','KeyA','KeyS','KeyD','KeyQ','KeyE','KeyI','KeyK','KeyJ','KeyL','KeyU','KeyO','KeyZ','KeyX','KeyR','KeyT','KeyB','KeyH','Space','ShiftLeft','ShiftRight','ControlLeft','ControlRight']);
