window.addEventListener('keydown',e=>{if(S.atCenter||!e.code.startsWith('Arrow')||e.ctrlKey||e.metaKey||e.altKey||$('#modal','dialog').open||!acceptsFlightKey(e.target,e.code))return;e.preventDefault();cameraKeys.add(e.code);});
