function catalog(){const q=$('#search','input').value.toLowerCase();$('#parts','div').innerHTML=Object.entries(PARTS).filter(([k,d])=>(S.category==='すべて'||S.category===d.cat)&&(`${d.name} ${d.code} ${k}`).toLowerCase().includes(q)).map(([k,d])=>`<button class="partcard" data-type="${k}" title="${d.desc}"><span class="partcode">${d.code}</span><em>+</em><img src="${assetModel(k).userData.thumbnail}" alt=""><strong>${d.name}</strong></button>`).join('');$$('.partcard','button').forEach(b=>b.onclick=()=>{const type=dataValue(b,'type');if(!isPartType(type))throw Error('不明な部品です: '+type);beginPlacement(type);});}
