async function boot(){try{$('#catalogCount','span').textContent=String(Object.keys(PARTS).length);const loader=new GLTFLoader();await Promise.all(Object.keys(PARTS).map(async type=>{const gltf=await loader.loadAsync(`./assets/parts/${PARTS[type].model||type}.glb`);assets.set(type,gltf.scene);assetBounds.set(type,new T.Box3().setFromObject(gltf.scene));}));const thumbRenderer=new T.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});thumbRenderer.setSize(180,120);thumbRenderer.setPixelRatio(1);thumbRenderer.toneMapping=T.ACESFilmicToneMapping;thumbRenderer.toneMappingExposure=1.05;const ts=new T.Scene();ts.environment=scene.environment;ts.add(new T.HemisphereLight('#ffffff','#6e8998',1.2));const light=new T.DirectionalLight('#fff4db',2.5);light.position.set(4,6,5);ts.add(light);const tc=new T.PerspectiveCamera(33,1.5,.01,100);for(const [type,model]of assets){const clone=model.clone(true);ts.add(clone);const b=new T.Box3().setFromObject(clone),center=b.getCenter(new T.Vector3()),s=b.getSize(new T.Vector3()).length();tc.position.copy(center).add(new T.Vector3(1.3,.8,1.8).normalize().multiplyScalar(s*1.8));tc.lookAt(center);thumbRenderer.render(ts,tc);model.userData.thumbnail=thumbRenderer.domElement.toDataURL();ts.remove(clone);}thumbRenderer.dispose();const shroud=await loader.loadAsync('./assets/parts/engine-shroud.glb');assets.set('engine-shroud',shroud.scene);const canopy=await loader.loadAsync('./assets/parts/parachute-open.glb');canopy.scene.traverse((o:T.Object3D)=>{if(o instanceof T.Mesh&&!Array.isArray(o.material))o.material.side=T.DoubleSide;});assets.set('parachute-open',canopy.scene);await Promise.all(['north','east'].map(async id=>{const marker=await loader.loadAsync('./assets/scenery/survey-'+id+'.glb');assets.set('survey-'+id,marker.scene);}));const pad=await loader.loadAsync('./assets/scenery/launchpad.glb');assets.set('launchpad',pad.scene);catalog();restoreWorkspace();rebuild();frame();$('#loading','div').hidden=true;await initializeCenter();}catch(e){console.error(e);$('#loading','div').innerHTML='<strong>部品を読み込めませんでした</strong><span>ページを再読み込みしてください。</span>';}}
boot();

function refreshDockedFlight(next:Flight){const blueprint=S.parts;keys.clear();S.launchPilot=null;for(const e of exhaust){e.mesh.geometry.dispose();e.mesh.material.dispose();}exhaust.length=0;S.flight=next;S.parts=structuredClone(next.parts);rebuild();startFlight(next);S.parts=blueprint;syncFlightControls();}

function portOptions(select:HTMLSelectElement,parts:FlightPart[],chosen:string|null|undefined){const ids=parts.map(p=>p.id).join('|');if(select.dataset.ids!==ids){select.replaceChildren(...parts.map((p,i)=>{const o=document.createElement('option');o.value=p.id;o.textContent='DP-12 #'+(i+1)+' · '+p.p.map(n=>n.toFixed(1)).join(',');return o;}));select.dataset.ids=ids;}if(typeof chosen==='string'&&parts.some(p=>p.id===chosen))select.value=chosen;return select.value;}
function updateDocking(){
 const panel=$('#dockingPanel','details');const docked=S.flight;panel.hidden=!docked||!canControl(docked);if(!docked||panel.hidden){S.dockingArmed=null;return;}const bonds=$('#dockBonds','div');bonds.replaceChildren();
 for(const p of docked.parts.filter(p=>p.dockPartner&&p.parent===p.dockPartner)){const button=document.createElement('button');button.textContent='結合ポートを分離';button.onclick=()=>{try{refreshDockedFlight(undockVessel(currentFlight(),p.id));gameAudio.play('stage');notify('再分離しました。相手機体を目標に指定できます。');}catch(e){notify(errorMessage(e));}};bonds.append(button);}
 const target=docked.navigationTarget,own=docked.parts.filter(p=>PARTS[p.type].docking&&!p.dockPartner),other=target?.parts.filter(p=>PARTS[p.type].docking&&!p.dockPartner)||[];
 const ownId=portOptions($('#ownPort','select'),own,docked.dockingPorts?.own),targetId=portOptions($('#targetPort','select'),other,docked.dockingPorts?.target);selectDockingPorts(docked,ownId&&targetId?ownId:null,ownId&&targetId?targetId:null);
 const guide=docked.dockingPorts?portGuidance(docked,ownId,target,targetId):null,status=guide&&target?dockingStatus(docked,ownId,target,targetId):null;
 dockingWindow.readings(guide,status);$('#portGuide','div').hidden=!guide;$('#portFrame','input').checked=docked.portTranslationEnabled;
 if(guide){$('#portReadings','small').textContent='軸距離 '+guide.axial.toFixed(2)+' m · 接近 '+guide.closing.toFixed(2)+' m/s';drawPortScope($('#portCrosshair','canvas'),guide);}
 $('#dockStatus','small').textContent=status?(status.ready?'結合できます':status.reason):target?'双方に空きポートが必要です':'他の機体を目標に指定してください';
 if(S.dockingArmed&&(S.dockingArmed.flight!==S.flight||S.dockingArmed.own!==ownId||S.dockingArmed.target!==targetId))S.dockingArmed=null;const connect=()=>{S.dockingArmed=null;try{const live=currentFlight();if(!target)throw Error('目標の機体がありません');refreshDockedFlight(dockVessels(live,target,ownId,targetId));gameAudio.play('dock');notify('ドッキング完了。1機として操縦できます。');}catch(e){notify(errorMessage(e));}};$('#dockButton','button').disabled=!guide;$('#autoDock','button').disabled=!guide&&!dockingPilot.active;$('#autoDock','button').textContent=dockingPilot.active?'自動ドッキングを中止':'自動ドッキング';$('#autoDockStatus','small').textContent=dockingPilot.state==='idle'?'':'自動ドッキング：'+dockingPilot.message;$('#autoDock','button').onclick=()=>{if(dockingPilot.active){dockingPilot.stop('cancelled','中止しました');S.dockingArmed=null;return;}try{dockingPilot.start(S.flight);S.dockingArmed={flight:S.flight,own:ownId,target:targetId};notify('自動ドッキング開始：整列→回り込み→待機点→最終接近の順に進みます。操縦キーで中止。');}catch(e){notify(errorMessage(e));}};$('#dockButton','button').textContent=S.dockingArmed?'結合待機を解除':status?.ready?'目標と結合':'結合待機（接近は手動）';$('#dockButton','button').onclick=()=>{if(!guide||!status)return;if(S.dockingArmed){S.dockingArmed=null;return;}if(status.ready){connect();return;}S.dockingArmed={flight:S.flight,own:ownId,target:targetId};notify('結合待機：条件がそろうと結合します。接近と減速は手動です。');};if(S.dockingArmed&&status?.ready)connect();
}
$('#portPower','select').onchange=()=>{keys.clear();$('#portPower','select').blur();};
for(const id of ['ownPort','targetPort'])$('#'+id,'select').onchange=()=>{if(S.flight){keys.clear();S.dockingArmed=null;selectDockingPorts(S.flight,$('#ownPort','select').value,$('#targetPort','select').value);}blurActive();};
