function loadDesigns():import('./design-library.js').DesignLibrary{const raw=localStorage.getItem(DESIGN_LIBRARY_KEY);if(raw){if(raw.length>12000000)throw Error('設計一覧が大きすぎます');return readDesignLibrary(JSON.parse(raw));}const legacy=localStorage.getItem(storageKey('craft'));if(!legacy)return {version:1,designs:[]};const old=JSON.parse(legacy);return appendDesign({version:1,designs:[]},{name:typeof old.name==='string'?old.name:'以前の保存',parts:validateCraft(old),bay:'vab',environment:'land'},'legacy',0);}
function saveDesign(){try{const library=appendDesign(loadDesigns(),{name:$('#craftName','input').value,parts:S.parts,bay:S.bayMode,environment:$('#environment','select').value});localStorage.setItem(DESIGN_LIBRARY_KEY,JSON.stringify(library));if(S.atCenter)refreshCenter();notify('設計一覧に新しい版を保存しました · '+library.designs.length+'件');return true;}catch(e){notify('保存できませんでした：'+errorMessage(e));return false;}}
$('#save','button').onclick=saveDesign;
function highlightCenterFacility(id:string|null){const facility=Object.entries(CENTER_FACILITIES).find(([key])=>key===id)?.[1];$('#centerFacilityName','h2').textContent=facility?.name||'施設を選んで出発';$('#centerFacilityDescription','p').textContent=facility?.description||'建物にポインターを合わせると役割を表示します。';for(const [key,item]of Object.entries(CENTER_FACILITIES))$('#'+item.button,'button').classList.toggle('facilityHighlighted',key===id);}
for(const [id,item]of Object.entries(CENTER_FACILITIES)){const button=$('#'+item.button,'button');button.addEventListener('pointerenter',()=>S.centerView?.pointFacility(id));button.addEventListener('pointerleave',()=>S.centerView?.pointFacility(null));button.addEventListener('focus',()=>S.centerView?.focusFacility(id));button.addEventListener('blur',()=>S.centerView?.focusFacility(null));}
function openCenterFacility(id:string){if(id==='vab'||id==='sph'){enterWorkshop(id);return;}if(id==='tracking')openTracking();else if(id==='pad'||id==='runway')openLaunchLibrary(id);}
function hasMapOrbit<R extends {position?:unknown;segments?:unknown}>(row:R):row is R&{position:NonNullable<R['position']>;segments:NonNullable<R['segments']>}{return row.position!==undefined&&row.position!==null&&row.segments!==undefined&&row.segments!==null;}
function openTracking(focusId:string|null=null){try{const rows=worldTrackingList(S.parkedWorld,{includeOrbit:true});if(!rows.every(hasMapOrbit))throw Error('軌道図の位置情報がありません');showModal('<div class="eyebrow">TRACKING STATION</div><h2>追跡施設</h2><p>機体を選んで操縦・観察を再開します。選択するまでは時間が停止しています。</p><div id="trackingMapHost"></div><div id="trackingRows"></div>');$('#modal','dialog').classList.add('trackingDialog');const list=$('#trackingRows','div'),map=mountTrackingMap($('#trackingMapHost','div'),rows,id=>{for(const row of list.querySelectorAll('article'))row.classList.toggle('selectedVessel',row.dataset.vessel===id);});appendRecoveryUndo(list);if(!rows.length){const empty=document.createElement('p');empty.textContent='進行中の飛行はありません。VAB/SPHで機体を作って出発してください。';list.append(empty);return;}for(const [index,item]of rows.entries()){const row=document.createElement('article');row.className='facilityRow'+(index===0?' selectedVessel':'');row.dataset.vessel=String(item.id);row.style.setProperty('--vessel-color',TRACKING_COLORS[index%TRACKING_COLORS.length]);const name=document.createElement('strong'),description=document.createElement('p');name.textContent=(index+1)+'. '+item.name;const select=document.createElement('button');select.textContent='軌道図で選択';select.onclick=()=>{map.select(item.id);for(const other of list.querySelectorAll('article'))other.classList.toggle('selectedVessel',other===row);};row.append(select);description.textContent=item.parts+'部品 · 高度 '+(item.altitude/1000).toFixed(2)+' km · 軌道 '+item.speed.toFixed(1)+' m/s · 地表 '+item.surfaceSpeed.toFixed(1)+' m/s · T+ '+item.time.toFixed(1)+'s · '+item.status;row.append(name,description);for(const burn of item.pendingBurns){const note=document.createElement('p');note.textContent=burn.label+' · UT '+burn.time.toFixed(1)+' s · '+(burn.overdue?'予定時刻を過ぎています。操縦を再開して再計画・削除を確認':'噴射まで '+formatDuration(burn.time-item.universalTime));row.append(note);}for(const [observe,label]of [[false,'操縦を再開'],[true,'観察を再開']] as const){const button=document.createElement('button');button.textContent=label;button.disabled=!observe&&!item.controllable;button.onclick=()=>{try{const world=S.parkedWorld,id=item.id;if(!world)throw Error('保存された世界がありません');if(id===undefined)throw Error('機体の識別子がありません');const selection=selectWorldVessel(world,id,{observe});$('#modal','dialog').close();resumeFromCenter(selection);}catch(e){$('#centerNotice','p').textContent=errorMessage(e);}};row.append(button);}const retire=document.createElement('button');retire.textContent=item.recovery.action;retire.onclick=()=>confirmRecovery(item);row.append(retire);list.append(row);if(item.id===focusId||item.anchorPartId===focusId){select.click();row.scrollIntoView({block:'center'});}}}catch(e){$('#centerNotice','p').textContent='追跡一覧を開けませんでした：'+errorMessage(e);}}
function openLaunchLibrary(facility:string){try{const library=loadDesigns();showModal('<div class="eyebrow">LAUNCH OPERATIONS</div><h2>'+ (facility==='workshop'?'保存した設計':facility==='pad'?'発射台':'滑走路')+'</h2><p>保存した設計の版を選びます。作業中の設計は保持されます。</p><button id="saveDraftToLibrary">作業中の設計を一覧に保存</button><div id="launchDesignRows"></div>');$('#saveDraftToLibrary','button').onclick=()=>{if(saveDesign())openLaunchLibrary(facility);else {const message=document.createElement('p');message.textContent='保存できませんでした。機体が空でないか、ブラウザの保存容量を確認してください。';$('#launchDesignRows','div').prepend(message);}};const list=$('#launchDesignRows','div');if(!library.designs.length){const empty=document.createElement('p');empty.textContent='まだ保存した設計がありません。上のボタンで現在の設計を保存できます。';list.append(empty);}for(const design of [...library.designs].reverse()){const row=document.createElement('article');row.className='facilityRow';const name=document.createElement('strong'),info=document.createElement('p'),button=document.createElement('button');name.textContent=design.name;info.textContent=design.parts.length+'部品 · '+design.bay.toUpperCase()+' · '+(design.savedAt?new Date(design.savedAt).toLocaleString():'以前の保存');button.textContent=facility==='workshop'?'設計を読み込む':facility==='pad'?'発射台から出発':'滑走路から出発';button.onclick=()=>{if(facility==='workshop'){if(S.flight)return;$('#modal','dialog').close();loadData({version:1,name:design.name,parts:design.parts});setBay(design.bay);$('#environment','select').value=design.environment;updateDepartureButton(document,design.environment);persistWorkspace();}else launchStoredDesign(library,design.id,facility);};row.append(name,info,button);list.append(row);}}catch(e){$('#centerNotice','p').textContent='設計一覧を開けませんでした：'+errorMessage(e);}}
function launchStoredDesign(library:import('./design-library.js').DesignLibrary,id:string,facility:string){try{launchAdditional(designForLaunch(library,id,facility));}catch(e){$('#centerNotice','p').textContent=errorMessage(e);}}

$('#centerTracking','button').onclick=()=>openTracking();$('#centerPad','button').onclick=()=>openLaunchLibrary('pad');$('#centerRunway','button').onclick=()=>openLaunchLibrary('runway');

$('#load','button').onclick=()=>{if(!S.flight)openLaunchLibrary('workshop');};

function finishPractice(){
 if(!S.practiceSession)return;
 const home=S.practiceSession.home;
 if(S.flight)endFlight();S.practiceSession=null;
 S.parkedWorld=home.world;S.universalTime=home.world.universalTime;
 S.parts=home.workshop.parts;$('#craftName','input').value=home.workshop.name;
 setBay(home.workshop.bay);$('#environment','select').value=home.workshop.environment;
 keys.clear();physicsClock.reset();rebuild();frame();updateInfo();
 notify('練習を終了しました。通常世界の機体・時刻・設計に戻りました。');
}
function isLaunchSiteError(e:unknown):e is import('./launch-clearance.js').LaunchSiteError{return e instanceof Error&&(!('blockers' in e)||e.blockers===undefined||Array.isArray(e.blockers));}
function launchAdditional(design:import('./practice-session.js').PracticeDesign&{bay?:string}){
 if(S.flight||S.practiceSession){notify('現在の飛行を終了してから出発してください');return;}
 let next:Flight|null=null,candidate:PracticeSession|null=null;
 const draft={parts:S.parts,name:$('#craftName','input').value,environment:$('#environment','select').value,bay:S.bayMode};
 try{
  const home=gameRecord({world:S.parkedWorld??worldFromFlight(null,{universalTime:S.universalTime}),draft});
  const practice=departureMode(design.environment).mode==='practice';
  if(practice){
   if(S.workspaceError)throw Error('通常世界の保存エラーを解消してから練習を開始してください');
   candidate=new PracticeSession(home,design);candidate.saveHome(localStorage);
  }
  const launchedWorld=candidate?candidate.initialWorld:launchWorld(home.world,design);
  const launchedRecord=flightFromWorld(launchedWorld);if(!launchedRecord)throw Error('出発した機体の記録がありません');next=loadFlight(launchedRecord);S.launchPartOrigins=new Map(next.parts.map((p,i)=>[p.id,design.parts[i]?.id]));
  S.practiceSession=candidate;$('#modal','dialog').close();enterWorkshop(design.bay||S.bayMode);
  S.parts=structuredClone(next.parts);$('#craftName','input').value=next.vesselName;
  $('#environment','select').value=next.environment;rebuild();startFlight(next);S.activeFlightName=next.vesselName;
  S.parkedWorld=launchedWorld;S.parts=draft.parts;$('#craftName','input').value=draft.name;
  $('#environment','select').value=draft.environment;S.bayMode=draft.bay;persistWorkspace();
  if(practice)notify('独立した練習を開始しました。通常世界は停止・保持されています。');else{const departure=launchedWorld.history.at(-1);if(!departure)throw Error('出発の記録がありません');notify(historyActionLabel(departure)+' · 他の機体 '+(fleet(currentFlight()).length-1)+'機を保持');}
 }catch(e){
  if(S.practiceSession){if(next===S.flight)next=null;finishPractice();}
  if(next&&next!==S.flight)next.dispose();
  S.parts=draft.parts;$('#craftName','input').value=draft.name;$('#environment','select').value=draft.environment;S.bayMode=draft.bay;
  notify(errorMessage(e));
  if(isLaunchSiteError(e)&&e.code==='launch_site_occupied'){const blockers=e.blockers;if(!blockers)throw Error('出発地点を使用中の機体が分かりません');showModal('<h2>出発地点を使用中</h2><div id="launchBlockers"></div>');for(const item of blockers){const row=document.createElement('article'),name=document.createElement('strong'),button=document.createElement('button');row.className='facilityRow';name.textContent=item.name;button.textContent='追跡施設で確認';button.onclick=()=>{showCenter();openTracking(item.id);};row.append(name,button);$('#launchBlockers','div').append(row);}return;}
  if($('#modal','dialog').open){const message=document.createElement('p');message.textContent=errorMessage(e);$('#modalBody','div').append(message);}
 }
}

function appendRecoveryUndo(list:HTMLElement){if(!S.recoveryUndo||JSON.stringify(S.parkedWorld)!==S.recoveryUndo.after)return;const text=document.createElement('p'),button=document.createElement('button');text.textContent=S.recoveryUndo.message+'。再開・追加出発・再読込するまでは取り消せます。';button.textContent='直前の回収・運用終了を取り消す';button.onclick=()=>{if(!S.recoveryUndo||JSON.stringify(S.parkedWorld)!==S.recoveryUndo.after)return;const after=S.parkedWorld;S.parkedWorld=structuredClone(S.recoveryUndo.before);if(!persistWorkspace()){S.parkedWorld=after;return;}S.recoveryUndo=null;refreshCenter();openTracking();};list.append(text,button);}
function confirmRecovery(item:import('./world-operations.js').WorldTrackingRow){showModal('<div class="eyebrow">MISSION OPERATIONS</div><h2 id="retireTitle"></h2><p id="retireSummary"></p><p>この機体だけを飛行一覧から外します。保存設計と他の機体は保持します。直後に取り消せますが、再開・追加出発・再読込後は取り消せません。</p><button id="confirmRetire">実行</button><button id="cancelRetire">戻る</button>');$('#retireTitle','h2').textContent=item.recovery.action+'の確認';$('#retireSummary','p').textContent=item.name+' · '+item.parts+'部品 · '+item.recovery.reason;$('#cancelRetire','button').onclick=()=>openTracking();$('#confirmRetire','button').onclick=()=>{try{const world=S.parkedWorld,id=item.id;if(!world)throw Error('保存された世界がありません');if(id===undefined)throw Error('機体の識別子がありません');const before=structuredClone(world),result=retireWorldVessel(world,id,item.recovery.recoverable?'recover':'terminate');S.parkedWorld=result.world;if(!persistWorkspace()){S.parkedWorld=before;throw Error('保存できなかったため機体を保持しました');}S.recoveryUndo={before,after:JSON.stringify(S.parkedWorld),message:result.removed.name+'を'+result.removed.action+'しました'};refreshCenter();openTracking();}catch(e){$('#retireSummary','p').textContent=errorMessage(e);}};}

function branchGhost(branch:PartBranch){const group=new T.Group(),preview=placeBranch([],branch,{position:[0,0,0],rotation:[0,0,0]});for(const p of preview.parts){const model=cloneModel(p.type);model.position.fromArray(p.p);model.rotation.set(...p.r);group.add(model);}return group;}
function renderAssemblyTree(){const panel=$('#assemblyTree','details'),list=$('#assemblyTreeRows','ol');panel.hidden=!!S.flight;const scroll=list.scrollTop;list.replaceChildren();if(S.flight)return;const branch=S.selected?descendants(S.parts,S.selected):new Set();for(const [index,item]of assemblyTree(S.parts).entries()){const row=document.createElement('li'),button=document.createElement('button');row.style.paddingLeft=Math.min(item.depth,12)*12+'px';button.textContent=(index+1)+'. '+PARTS[item.type].code+' '+PARTS[item.type].name+' · 枝'+item.count+' · 段'+item.stage;button.classList.toggle('branchMember',branch.has(item.id));button.setAttribute('aria-pressed',String(item.id===S.selected));button.onclick=()=>{cancelPlacement();select(item.id);};row.append(button);list.append(row);}list.scrollTop=scroll;$('#assemblyTreeCount','b').textContent=String(S.parts.length);}

function clearInterferenceHighlight(){fuelOverlay.clear();document.getElementById('fuelNetwork')?.setAttribute('aria-pressed','false');for(const o of [...interferenceOverlay.children]){if(o instanceof T.LineSegments){o.geometry.dispose();disposeMaterial(o.material);}interferenceOverlay.remove(o);}for(const row of document.querySelectorAll('.interferencePairActive'))row.classList.remove('interferencePairActive');}
function showInterferencePair(pair:import('./assembly-interference.js').InterferencePair,focusId:string,row:HTMLElement){if(S.flight)return;cancelPlacement();select(focusId);for(const [index,id]of [pair.a,pair.b].entries()){const p=S.parts.find(p=>p.id===id);if(!p)continue;for(const box of partInterferenceBounds(p,assetBounds)){const shape=new T.BoxGeometry(...box.half.clone().multiplyScalar(2).toArray()),edges=new T.EdgesGeometry(shape);shape.dispose();const line=new T.LineSegments(edges,new T.LineBasicMaterial({color:index?'#55dce8':'#ff9c56',depthTest:false}));line.position.copy(box.center);line.quaternion.copy(box.quaternion);line.renderOrder=20;interferenceOverlay.add(line);}}row.classList.add('interferencePairActive');}
function renderInterferences(){const list=$('#interferenceRows','div');list.replaceChildren();if(S.flight)return;const result=assemblyInterferences(S.parts,assetBounds);$('#interferenceCount','b').textContent=String(result.total);$('#interferenceSummary','p').textContent=result.total?(result.total+' 組。'+(result.total>result.pairs.length?'先頭 '+result.pairs.length+' 組を表示。':'')+'部品名を選ぶと橙・水色の箱で表示します。'):'箱同士の明確な重なりはありません。';const indices=new Map(S.parts.map((p,i)=>[p.id,i+1]));for(const pair of result.pairs){const row=document.createElement('article');row.className='interferencePair';for(const [index,id]of [pair.a,pair.b].entries()){const p=partById(S.parts,id),button=document.createElement('button');button.textContent=(index?'水色':'橙')+' '+indices.get(id)+'. '+PARTS[p.type].code+' '+PARTS[p.type].name;button.onclick=()=>showInterferencePair(pair,id,row);row.append(button);}list.append(row);}}

function updateWorkshop(){if(S.flight)return;const bounds=new T.Box3().setFromObject(craftRoot),layout=workshopLayout(bounds,camera.fov,camera.aspect);bay.position.fromArray(layout.origin);S.workshopFloor=layout.origin[1];room.scale.fromArray(layout.roomScale);workshopDeck.scale.set(layout.platformScale,1,layout.platformScale);workshopGround.scale.set((layout.gridSize+10)/90,1,(layout.gridSize+10)/90);if(S.workshopGridSize!==layout.gridSize){grid.removeFromParent();grid.geometry.dispose();for(const material of Array.isArray(grid.material)?grid.material:[grid.material])material.dispose();S.workshopGridSize=layout.gridSize;const step=Math.max(1,Math.ceil(S.workshopGridSize/200));grid=new T.GridHelper(S.workshopGridSize,Math.ceil(S.workshopGridSize/step),'#647984','#435963');grid.position.y=-.16;bay.add(grid);}const fit=workshopFrame(bounds,camera.fov,camera.aspect);if(fit){controls.maxDistance=fit.maxDistance;scene.fog=new T.Fog('#293c49',fit.fogNear,fit.fogFar);}}

const capturePanel=mountCapturePanel($('#transferPanel','section'),()=>S.flight,message=>{syncFlightControls();notify(message);});
const descentPanel=mountDescentPanel($('#capturePanel','section'),()=>S.flight,()=>syncFlightControls());
mountFlightLayout();
descentPanel.mountWindow();
const runwayPanel=mountRunwayPanel(document,()=>({flight:S.flight,atCenter:S.atCenter}));
const maneuverPanel=mountManeuverPanel(document,()=>({flight:S.flight,atCenter:S.atCenter}),{sync:()=>{if(S.flight)syncFlightControls();},claim:()=>{orbitalPanel.stop();cruisePanel.stop();S.launchPilot=null;keys.clear();$('#warp','select').value='1';physicsClock.reset();$('#warpStatus','small').textContent=flightPause.paused?'一時停止 · Pで再開':'通常速度へ：自動噴射を開始';}});
const orbitalPanel=mountOrbitalAscent(document,()=>({flight:S.flight,atCenter:S.atCenter}),{sync:()=>{if(S.flight)syncFlightControls();},onRemoved:id=>{const object=objects.get(id);if(object)object.visible=false;},claim:()=>{maneuverPanel.stop();cruisePanel.stop();S.launchPilot=null;keys.clear();$('#warp','select').value='1';physicsClock.reset();$('#warpStatus','small').textContent=flightPause.paused?'一時停止 · Pで再開':'通常速度へ：自動投入を開始';}});
const cruisePanel=mountCruisePanel(document,()=>({flight:S.flight,atCenter:S.atCenter}),{sync:()=>syncFlightControls(),claim:()=>{maneuverPanel.stop();orbitalPanel.stop();S.launchPilot=null;$('#autoLaunch','button').textContent='自動軌道投入（見本用）';$('#warp','select').value='1';physicsClock.reset();$('#warpStatus','small').textContent=flightPause.paused?'一時停止 · Pで再開':'通常速度へ：自動操縦を開始';}});
const flightPause=mountFlightPause(document,{keys,clock:physicsClock,onChange:()=>{if(S.flight)updateFlightControls(document,S.flight);}});
const dockingWindow=mountDockingWindow(()=>S.flight);
const ascentPanel=mountAscentPanel($('#descentPanel','section'),()=>S.flight,()=>syncFlightControls());
const departurePanel=mountDeparturePanel($('#ascentPanel','details'),()=>S.flight,message=>{syncFlightControls();if(message)notify(message);});
const stageVisibility=mountStageVisibility(()=>objects);
const deliveryPanel=mountDeliveryPanel(document,()=>({flight:S.flight,world:S.parkedWorld,history:S.parkedWorld?.history??[],practice:!!S.practiceSession,atCenter:S.atCenter}),notify,probeId=>{
 try{
  if(S.practiceSession)return;
  if(!S.flight){const world=S.parkedWorld,target=world?.vessels.find(v=>v.parts.some(p=>p.id===probeId));if(!world||!target)throw Error('観測機が見つかりません');resumeFromCenter(selectWorldVessel(world,target.vesselId,{observe:!canControl({parts:target.parts,crashed:target.state.crashed})}));}
  else{const target=fleet(S.flight).find(v=>v.parts.some(p=>p.id===probeId));if(!target)throw Error('観測機が見つかりません');if(canControl(target)){switchVessel(target);}else{S.trackedDebris=target;const focus=vesselCenter(target);frameTrackedVessel(controls,focus,bodyUp(focus,S.flight.universalTime));flightFocus.copy(focus);updateDebrisList();}}
 }catch(error){notify(errorMessage(error));}
});
const buoyancyPanel=mountBuoyancyPanel(document,scene,()=>({parts:S.parts,flight:S.flight,atCenter:S.atCenter}),comMarker);
const designDiagnostics=mountDesignDiagnostics($('#checks','div'),()=>({parts:S.parts,flight:S.flight}),id=>{cancelPlacement();select(id);$('#selection','div').scrollIntoView({block:'nearest'});},balance=>thrustOverlay.update(balance),ids=>stageVisibility.update(ids));
const returnPanel=mountReturnPanel($('#ascentPanel','details'),()=>S.flight,message=>{syncFlightControls();if(message)notify(message);},{isPractice:()=>!!S.practiceSession});
const trajectoryPanel=mountTrajectoryPanel($('.mapContent','div'),()=>{
 if(!S.flight)return null;let burn:import('./trajectory.js').TrajectoryBurn|null=null,note='';const time=S.flight.universalTime;
 if($('#planEnabled','input').checked){const preview=maneuverPreview(flightCenter(),S.flight.vel,planLocation(),planDeltaV(),time);burn={time:preview.universalTime,deltaV:preview.impulse.toArray()};}
 else if(S.flight.maneuver&&!S.flight.maneuver.complete){const node=S.flight.maneuver,burnTime=node.capture?.midTime??node.returnPlan?.midTime??node.departure?.midTime??node.universalTime??time+node.time-S.flight.time;if(burnTime>=time)burn={time:burnTime,deltaV:[...node.remaining]};else note='固定計画は過去のため比較対象外';}
 return {position:flightCenter().clone(),velocity:S.flight.vel.clone(),time,burn,note,name:S.flight.vesselName||'機体'};
});

function updateTransferGuide(){const guided=S.flight,g=guided?.transferGuide,panel=$('#transferPanel','section');panel.hidden=!g;if(!g||!guided)return;const until=g.startTime-guided.universalTime,remaining=g.target-g.delivered,early=g.firstBurnTime!==null?g.firstBurnTime-g.startTime:null;
 $('#transferStatus','p').textContent=g.firstBurnTime===null?(until>0?'噴射開始まで '+until.toFixed(1)+'秒 · SAS順行・スロットル0で待機':'噴射時刻です（'+(-until).toFixed(1)+'秒経過）'):remaining<=0?(guided.throttle>0?'目標Δv到達 — 今すぐ噴射停止':'噴射完了。軌道マップで接近予測を再計算してください'):(remaining<100?'10%へ絞って調整 · 残り ':'噴射中 · 残り ')+remaining.toFixed(1)+' m/s';
 $('#transferProgress','p').textContent='順行噴射量 '+g.delivered.toFixed(1)+' / '+g.target.toFixed(1)+' m/s · 全開の目安 '+g.burnTime.toFixed(1)+'秒'+(early!==null&&Math.abs(early)>2?' · 開始ずれ '+early.toFixed(1)+'秒：到達は再予測が必要':'');
 $('#transferIgnite','button').disabled=!canControl(guided)||guided.crashed;
}
$('#transferIgnite','button').onclick=()=>{if(!S.flight||!canControl(S.flight)||S.flight.crashed)return;if(S.flight.stage<0)stage();S.flight.throttle=1;$('#throttle','input').value='100';updateTransferGuide();};
$('#transferCutoff','button').onclick=()=>{if(!S.flight)return;S.flight.throttle=0;$('#throttle','input').value='0';updateTransferGuide();};

$('#transferFine','button').onclick=()=>{if(!S.flight||!canControl(S.flight)||S.flight.crashed)return;S.flight.throttle=.1;$('#throttle','input').value='10';updateTransferGuide();};
